const memo=m.resolution?.[method];
if(memo){const delta=n=>(n>=0?'+':'')+n;modal(memo.title,`<p>${esc(memo.body)}</p><div class="story-dispute"><p>${esc(window.LemmaNarrative.choiceBeat(mission,method))}</p></div><div class="status"><span class="pill">${delta(state.credits-before.credits)} CREDITS${captured?' · rival deduction included':''}</span><span class="pill">${delta(state.understanding-before.understanding)} UNDERSTANDING</span>${state.mission<E.MISSIONS.length?`<span class="pill">NEXT RIVAL HEAD START ${state.headstart}%</span>`:''}</div><button id="memo-continue">${state.phase==='ending'?'Read the campaign outcome →':'Return to headquarters →'}</button>`);$('memo-continue').onclick=()=>{$('modal').hidden=true};}
